'use strict';
(() => {
  const tr=(pt,en)=>settings.language==='en'?en:pt;
  const KEY='javalingo-student-v1',PRACTICE_KEY='javalingo-code-practice-v1';
  function read(key,initial){try{return {...initial,...JSON.parse(localStorage.getItem(key)||'{}')}}catch{return initial}}
  const profileColors={forest:['Verde clássico','#297c68'],indigo:['Índigo','#5766a6'],sunset:['Pôr do sol','#cb785c'],ocean:['Oceano','#258ca4'],rose:['Rosa','#aa678d'],midnight:['Azul noturno','#334867'],lavender:['Lavanda','#a282ca'],amethyst:['Ametista','#7654a8'],coral:['Coral','#e17d7c'],peach:['Pêssego','#e5a070'],terracotta:['Terracota','#ad6655'],sky:['Azul céu','#65a8db'],teal:['Turquesa','#47b5ad'],mint:['Menta','#79ba9e'],emerald:['Esmeralda','#339579'],gold:['Dourado','#c49c4f'],berry:['Framboesa','#b65c80'],plum:['Ameixa','#76517b'],olive:['Oliva','#879455'],cocoa:['Cacau','#8c6758']};
  const validProfileColor=value=>typeof value==='string'&&/^#[0-9a-f]{6}$/i.test(value);
  function profileInk(hex){const rgb=[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return .2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2]>.18?'#000':'#fff'}
  const profileFocus=['Explorando Java','Fundamentos','Orientação a objetos','Coleções e APIs','Swing','Projetos práticos'];
  let student=read(KEY,{name:'',photo:'',bio:'',cover:'forest',customColor:'#8074c7',focus:'Explorando Java',goal:3,seconds:0,started:Date.now(),last:Date.now()}),work=read(PRACTICE_KEY,{bits:{},attempts:0,drafts:{}}),api=null,apiRows=[],apiError='',dictionaryQuery='',dictionaryKind='all',dictionaryPage=0;
  student.bio=typeof student.bio==='string'?student.bio.slice(0,180):'';
  student.name=typeof student.name==='string'?student.name.slice(0,80):'';
  student.photo=typeof student.photo==='string'?student.photo:'';
  student.cover=student.cover==='custom'||Object.hasOwn(profileColors,student.cover)?student.cover:'forest';
  student.customColor=validProfileColor(student.customColor)?student.customColor:'#8074c7';
  student.focus=profileFocus.includes(student.focus)?student.focus:profileFocus[0];
  student.goal=[2,3,5,7].includes(Number(student.goal))?Number(student.goal):3;
  let profileSaveTimer=null;
  let draftTimer=null,family=0,variant=1,editorCode='',editorOutput=null,editorError='',editorReady=false,practiceFeedback='',practiceFilter='all',practicePage=0;
  const saveStudent=()=>{try{localStorage.setItem(KEY,JSON.stringify(student))}catch{}};
  const saveWork=()=>{try{localStorage.setItem(PRACTICE_KEY,JSON.stringify(work))}catch{}};
  const labelHours=()=>`${(student.seconds/3600).toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1})} h`;
  let lastTick=Date.now(),lastAction=Date.now();
  for(const event of ['pointerdown','keydown','scroll'])document.addEventListener(event,()=>lastAction=Date.now(),{passive:true});
  setInterval(()=>{const now=Date.now(),delta=Math.max(0,Math.min(30,(now-lastTick)/1000));lastTick=now;if(document.visibilityState==='visible'&&document.hasFocus()&&now-lastAction<120000){student.seconds+=delta;saveStudent()}},30000);
  const bitsFor=i=>{let result;try{result=Uint8Array.from(atob(work.bits[i]||''),c=>c.charCodeAt(0))}catch{result=new Uint8Array(400)}if(result.length!==400)result=new Uint8Array(400);return result};
  const isSolved=(i,n)=>!!(bitsFor(i)[Math.floor((n-1)/8)]&(1<<((n-1)%8)));
  function solve(i,n){const b=bitsFor(i),p=n-1,mask=1<<(p%8);if(b[Math.floor(p/8)]&mask)return false;b[Math.floor(p/8)]|=mask;work.bits[i]=btoa(String.fromCharCode(...b));progress.xp+=15;persist();updateStats();saveWork();return true}
  const solvedCount=()=>Object.keys(work.bits).reduce((total,i)=>total+[...bitsFor(i)].reduce((n,v)=>n+JAVA_HEX_BITS[v&15]+JAVA_HEX_BITS[v>>4],0),0);
  const coreCompleted=()=>TRACKS.filter(t=>completed(t)>=100);
  const completedRoutes=()=>Object.keys(javaMegaProgress).filter(id=>javaMegaCompleted(id)>=100).map(id=>findJavaTrack(id)).filter(Boolean);
  const earned=()=>[...coreCompleted(),...completedRoutes()];
  const stats=()=>({lessons:Object.keys(progress.done).length+Object.values(javaMegaProgress).reduce((a,d)=>a+[...d].reduce((b,c)=>b+JAVA_HEX_BITS[parseInt(c,16)],0),0),missions:Object.keys(missionState.done).length,streak:missionState.streak||0});
  function initials(){return (student.name.trim().split(/\s+/).map(x=>x[0]).slice(0,2).join('')||'JL').toUpperCase()}
  function avatar(){return student.photo?`<img src="${esc(student.photo)}" alt="Foto do aluno">`:`<span>${esc(initials())}</span>`}
  function updateHeaderProfile(){const button=document.querySelector('#topProfile');if(!button)return;button.querySelector('.top-profile-avatar').innerHTML=avatar();button.setAttribute('aria-label',student.name?'Abrir perfil de '+student.name:'Abrir meu perfil');button.title=student.name?'Perfil de '+student.name:'Meu perfil'}
  function setProfileCover(cover){
    if(cover!=='custom'&&!Object.hasOwn(profileColors,cover))return;
    student.cover=cover;saveStudent();
    const hero=app.querySelector('.profile-hero');if(hero){hero.className='profile-hero cover-'+cover;hero.style.setProperty('--profile-custom-color',student.customColor);hero.style.setProperty('--profile-custom-ink',profileInk(student.customColor))}
    app.querySelectorAll('[data-profile-cover]').forEach(button=>{const active=button.dataset.profileCover===cover;button.setAttribute('aria-pressed',String(active));button.innerHTML=active?icon('check'):''});
    const custom=app.querySelector('[data-profile-custom]');if(custom)custom.setAttribute('aria-pressed',String(cover==='custom'));
    const label=app.querySelector('#profileColorName');if(label)label.textContent=cover==='custom'?'Sua cor · '+student.customColor.toUpperCase():profileColors[cover][0];
    const hex=app.querySelector('#profileCustomHex');if(hex)hex.textContent=student.customColor.toUpperCase();
    const status=app.querySelector('#profileSaveStatus');if(status)status.textContent='Cor salva automaticamente neste aparelho';
  }
  function saveProfileFields(){const name=app.querySelector('#profileName'),bio=app.querySelector('#profileBio'),focus=app.querySelector('#profileFocus'),goal=app.querySelector('#profileGoal');if(!name)return;student.name=name.value.trim().slice(0,80);student.bio=(bio?.value||'').trim().slice(0,180);student.focus=profileFocus.includes(focus?.value)?focus.value:profileFocus[0];student.goal=[2,3,5,7].includes(Number(goal?.value))?Number(goal.value):3;saveStudent();updateHeaderProfile();const title=app.querySelector('#profileHeroName'),intro=app.querySelector('#profileHeroBio'),status=app.querySelector('#profileSaveStatus');if(title)title.textContent=student.name||'Seu perfil';if(intro)intro.textContent=student.bio||'Personalize seu espaço e acompanhe cada conquista.';if(status)status.textContent='Salvo automaticamente neste aparelho'}
  function invite(){return `<section class="hub-invite"><div><span class="eyebrow">NOVIDADES EM JAVA</span><h2>Seu próximo passo, do seu jeito.</h2><p>Consulte a linguagem, escreva programas que rodam e guarde as conquistas das trilhas completas.</p></div><div class="hub-invite-actions"><button data-hub-open="practice">${icon('terminal')} Prática de código</button><button data-hub-open="dictionary">${icon('book')} Dicionário Java</button><button data-hub-open="profile">${icon('spark')} Meu perfil</button></div></section>`}
  const oldHome=renderHome;renderHome=function(){oldHome();app.querySelector('.home-hero')?.insertAdjacentHTML('afterend',invite())};
  const oldRender=render;render=function(){if(['practice','dictionary','profile'].includes(screen)){setNav();updateStats();if(screen==='practice')renderPractice();if(screen==='dictionary')renderDictionary();if(screen==='profile')renderProfile();if(typeof applyLanguage==='function')applyLanguage();return}oldRender()};
  const oldNav=setNav;setNav=function(){oldNav();if(screen==='practice')$('#breadcrumb').textContent=tr('Prática de código','Coding practice');if(screen==='dictionary')$('#breadcrumb').textContent=tr('Dicionário Java','Java dictionary');if(screen==='profile')$('#breadcrumb').textContent=tr('Meu perfil','My profile')};
  // O dicionário busca sob demanda um índice compacto da API pública do JDK 17.
  async function loadApi(){if(api)return;try{let response=await fetch('java-api-17.json');if(!response.ok)throw Error('HTTP '+response.status);api=await response.json();apiRows=api.map(x=>({kind:x[1],name:x[0],group:x[2],search:`${x[0]} ${x[2]}`.toLocaleLowerCase()}));apiError=''}catch{apiError='Não foi possível carregar a API agora. Os conceitos principais continuam disponíveis.'}if(screen==='dictionary')drawDictionaryResults()}
  const manualRows=JAVA_CONCEPTS.filter(x=>x.length===4&&x.every(Boolean)).map(x=>({kind:'conceito',name:x[0],group:x[1],description:x[2],example:x[3],search:`${x[0]} ${x[1]} ${x[2]}`.toLocaleLowerCase()}));
  function dictionaryData(){return manualRows.concat(apiRows)}
  function sourceMap(){return `<details class="learn-sources"><summary>Como os 12 PDFs orientaram este conteúdo</summary><p>Os materiais foram usados como referência de temas e objetivos de estudo. Os exercícios e textos apresentados aqui foram criados para o JavaLingo; os livros de terceiros não são reproduzidos.</p><div>${JAVA_STUDY_REFERENCES.map(([title,topics])=>`<article><strong>${esc(title)}</strong><span>${esc(topics)}</span></article>`).join('')}</div></details>`}
  function renderDictionary(){app.innerHTML=`<div class="learn-page"><button class="back-link" data-hub-open="home">${icon('back')} Trilhas</button><div class="learn-head dictionary-head"><span class="eyebrow">CONSULTE · ENTENDA · EXPERIMENTE</span><h1>Dicionário Java</h1><p>Conceitos explicados em português e índice pesquisável de tipos, métodos e campos públicos da API Java 17. A biblioteca externa e seus frameworks aparecem somente no glossário didático.</p><div class="learn-stats"><span>${JAVA_CONCEPTS.length} conceitos comentados</span><span>${api?api.length.toLocaleString('pt-BR'):'40 mil+'} símbolos da API</span></div></div><div class="learn-controls"><label>Pesquisar termo ou assinatura<input id="javaDictQuery" type="search" placeholder="Ex.: recursão, java.util.List, Math.sqrt" value="${esc(dictionaryQuery)}" autocomplete="off"></label><label>Exibir<select id="javaDictKind"><option value="all">Tudo</option><option value="conceito" ${dictionaryKind==='conceito'?'selected':''}>Conceitos explicados</option><option value="tipo" ${dictionaryKind==='tipo'?'selected':''}>Tipos da API</option><option value="método" ${dictionaryKind==='método'?'selected':''}>Métodos da API</option><option value="campo" ${dictionaryKind==='campo'?'selected':''}>Campos da API</option></select></label></div><div id="javaDictResults" aria-live="polite"></div>${sourceMap()}</div>`;drawDictionaryResults();if(!api&&!apiError)loadApi()}
  function drawDictionaryResults(){const box=app.querySelector('#javaDictResults');if(!box)return;let q=dictionaryQuery.trim().toLocaleLowerCase(),list=dictionaryData().filter(x=>(dictionaryKind==='all'||x.kind===dictionaryKind)&&(!q||x.search.includes(q)));let pages=Math.max(1,Math.ceil(list.length/20));dictionaryPage=Math.min(dictionaryPage,pages-1);let rows=list.slice(dictionaryPage*20,dictionaryPage*20+20);box.innerHTML=`<p class="learn-count">${list.length.toLocaleString('pt-BR')} resultados ${apiError?`· ${esc(apiError)}`:''}</p><div class="dict-results">${rows.map(row=>{if(row.kind==='conceito')return `<article class="dict-card"><span>${esc(row.group)} · conceito</span><h2>${esc(row.name)}</h2><p>${esc(row.description)}</p><code>${esc(row.example)}</code></article>`;let full=row.name,at=full.indexOf('('),owner=full.slice(0,at<0?undefined:at).split('.').slice(0,-1).join('.'),pretty=at<0?full:`${full.slice(0,at)}${javaDescriptor(full.slice(at))}`,type=row.kind==='tipo'?full:owner;let module=row.group,href=`https://docs.oracle.com/en/java/javase/17/docs/api/${encodeURIComponent(module)}/${type.replaceAll('.','/')}.html`;return `<article class="dict-card"><span>${esc(module)} · ${esc(row.kind)}</span><h2>${esc(pretty)}</h2><p>${row.kind==='tipo'?'Tipo público da biblioteca Java.':'Membro público de '+esc(owner)+'. Os parâmetros e o retorno aparecem na assinatura acima.'}</p><a href="${href}" target="_blank" rel="noopener noreferrer">Documentação Java 17 ${icon('arrow')}</a></article>`}).join('')}</div><div class="learn-pages"><button data-dict-page="prev" ${dictionaryPage===0?'disabled':''}>Anterior</button><span>Página ${dictionaryPage+1} de ${pages}</span><button data-dict-page="next" ${dictionaryPage>=pages-1?'disabled':''}>Próxima</button></div><p class="learn-note">Índice de símbolos extraído das assinaturas públicas do JDK 17; alguns métodos estão sobrecarregados. O glossário explica conceitos; para contratos e detalhes completos da API, abra a documentação oficial.</p>`}
  function currentPractice(){return javaPractice(family,variant)}
  function renderPractice(){let current=currentPractice(),draft=work.drafts?.[current.id]||current.code,count=JAVA_PRACTICE_FAMILIES.length*JAVA_PRACTICE_VARIANTS;app.innerHTML=`<div class="learn-page"><button class="back-link" data-hub-open="home">${icon('back')} Trilhas</button><div class="learn-head practice-head"><span class="eyebrow">ESCREVA · EXECUTE · CORRIJA</span><h1>Ateliê de código Java</h1><p>${count.toLocaleString('pt-BR')} instâncias de prática em ${JAVA_PRACTICE_FAMILIES.length} famílias de problemas, cada uma com entradas diferentes. Resolva de verdade no editor, veja a saída e tente outros dados.</p><div class="learn-stats"><span>${solvedCount().toLocaleString('pt-BR')} resolvidas</span><span>${work.attempts||0} tentativas</span></div></div><div class="learn-controls"><label>Assunto<select id="javaPracticeFamily">${JAVA_PRACTICE_FAMILIES.map((f,i)=>`<option value="${i}" ${i===family?'selected':''}>${esc(f.group)} · ${esc(f.title)}</option>`).join('')}</select></label><label>Variação (1 a ${JAVA_PRACTICE_VARIANTS.toLocaleString('pt-BR')})<input id="javaPracticeNumber" type="number" min="1" max="${JAVA_PRACTICE_VARIANTS}" value="${variant}"></label><button class="button button-secondary" data-practice-go>Abrir</button></div><section class="practice-card"><div class="practice-head"><span class="eyebrow">${esc(current.group)} · ${esc(current.title)}</span><span>${isSolved(family,variant)?'✓ Resolvida':`#${family*JAVA_PRACTICE_VARIANTS+variant}`}</span></div><h2>${esc(current.title)}</h2><p>${esc(current.task)}</p><p class="task-brief"><strong>Dados deste desafio</strong><pre>${esc(current.code)}</pre></p><details><summary>Preciso de uma pista</summary><p>${esc(current.hint)}</p></details><div class="mission-editor-head"><strong>${icon('code')} Java · Main.java</strong><span>Edite e execute no quadro</span></div><iframe id="practice-editor" title="Editor Java executável" src="https://onecompiler.com/embed/java?listenToEvents=true&codeChangeEvent=true&hideLanguageSelection=true&hideNew=true&hideTitle=true&theme=${settings.theme==='dark'?'dark':'light'}" loading="lazy" referrerpolicy="strict-origin-when-cross-origin"></iframe><p class="learn-note">A execução do código ocorre no OneCompiler. O código digitado ali é processado por esse serviço.</p><div class="practice-actions"><button class="button button-primary" data-practice-check>${icon('check')} Verificar saída</button><button class="button button-secondary" data-practice-next>Próxima variação ${icon('arrow')}</button><button class="button button-plain" data-practice-random>Surpreenda-me</button></div><div id="practiceFeedback" role="status">${practiceFeedback}</div><details class="practice-manual"><summary>A saída não apareceu aqui? Conferir manualmente</summary><label>Código executado<textarea id="practiceManualCode" spellcheck="false">${esc(draft)}</textarea></label><label>Saída mostrada pelo compilador<textarea id="practiceManualOutput" spellcheck="false"></textarea></label><button class="button button-secondary" data-practice-manual>Comparar saída colada</button></details></section><p class="learn-note">A correção compara a saída desta instância e a estrutura pedida; isso não prova todos os casos nem impede uma saída fixa. Experimente mudar dados depois de acertar. O editor precisa de conexão.</p></div>`;editorCode=draft;editorOutput=null;editorError='';editorReady=false}
  function checkPractice(code,output,manual){let item=currentPractice();work.attempts=(work.attempts||0)+1;saveWork();let note;if(!code.trim())note='Escreva um programa antes de verificar.';else if(output===null||output===undefined)note='Execute o programa no editor primeiro. Se a saída não chegar, use os campos de verificação manual.';else if(editorError&&!manual)note=`Erro ao executar: ${editorError.slice(0,250)}`;else if(normalizeOutput(output)!==normalizeOutput(item.expected))note=`A saída ainda não confere. Esperado: ${item.expected.replaceAll('\n',' | ')}. Obtido: ${String(output).slice(0,140).replaceAll('\n',' | ')||'(vazio)'}.`;else if(!item.requires.test(code))note='A saída confere, mas falta usar o conceito pedido no código. Revise a tarefa.';else {let fresh=solve(family,variant);note=`✓ Passou neste teste! ${fresh?'+15 XP.':''} Tente alterar os dados para confirmar sua lógica.${manual?' A saída colada foi informada por você.':''}`}practiceFeedback=`<div class="practice-message ${note.startsWith('✓')?'ok':'retry'}">${esc(note)}</div>`;let box=app.querySelector('#practiceFeedback');if(box)box.innerHTML=practiceFeedback}
  app.addEventListener('load',e=>{if(e.target.id!=='practice-editor')return;let frame=e.target,item=currentPractice();setTimeout(()=>{if(screen==='practice'&&app.querySelector('#practice-editor')===frame){frame.contentWindow?.postMessage({eventType:'populateCode',language:'java',files:[{name:'Main.java',content:work.drafts?.[item.id]||item.code}]},'https://onecompiler.com');editorReady=true}},450)},true);
  window.addEventListener('message',e=>{let frame=app.querySelector('#practice-editor');if(screen!=='practice'||e.origin!=='https://onecompiler.com'||e.source!==frame?.contentWindow)return;let data=e.data;if(typeof data==='string'){try{data=JSON.parse(data)}catch{return}}if(!data||typeof data!=='object'||data.language&&String(data.language).toLowerCase()!=='java')return;let files=Array.isArray(data.files)?data.files:[],code=files.find(f=>/\.java$/i.test(f.name||''))?.content||files[0]?.content;if(editorReady&&typeof code==='string'&&code.length<50000){editorCode=code;clearTimeout(draftTimer);let draftId=currentPractice().id;draftTimer=setTimeout(()=>{work.drafts=work.drafts||{};work.drafts[draftId]=code;let keys=Object.keys(work.drafts);if(keys.length>25)delete work.drafts[keys[0]];saveWork()},600);let fallback=app.querySelector('#practiceManualCode');if(fallback&&document.activeElement!==fallback)fallback.value=code}let result=parseResult(data);if(result){editorOutput=result.output;editorError=result.error}});
  function profileBadges(){let tracks=earned(),s=stats(),extras=[['Primeira prática',s.lessons>=1,'Concluiu a primeira atividade de uma trilha.'],['Código em ação',solvedCount()>=1,'Resolveu uma prática executável.'],['Construtor de projetos',s.missions>=4,'Concluiu quatro etapas de campanha.'],['Constância',s.streak>=3,'Completou três dias seguidos de missões.']];return `<div class="badge-grid">${extras.map(([title,ok,detail])=>`<div class="badge ${ok?'earned':''}"><span>${icon(ok?'spark':'book')}</span><strong>${title}</strong><small>${detail}</small></div>`).join('')}${tracks.map((t,i)=>`<div class="badge earned" style="--accent:${esc(t.color)}"><span>${icon('spark')}</span><strong>${esc(t.title)}</strong><small>Trilha completa · 100/100 práticas</small><button data-cert="${i}">Baixar certificado</button></div>`).join('')}</div>`}
  function renderProfile(){
    let s=stats(),tracks=earned(),level=1+Math.floor(progress.xp/250),nextLevel=250-progress.xp%250;
    let nearest=TRACKS.reduce((best,t)=>completed(t)>completed(best)?t:best,TRACKS[0]),trackDone=completed(nearest);
    app.innerHTML=`<div class="learn-page profile-page"><button class="back-link" data-hub-open="home">${icon('back')} Trilhas</button>
      <div class="profile-hero cover-${student.cover}" style="--profile-custom-color:${student.customColor};--profile-custom-ink:${profileInk(student.customColor)}"><div class="profile-avatar">${avatar()}</div><div><span class="eyebrow">SUA JORNADA EM JAVA</span><h1 id="profileHeroName">${esc(student.name||'Seu perfil')}</h1><p>Nível ${level} · ${progress.xp.toLocaleString('pt-BR')} XP · desde ${new Date(student.started).toLocaleDateString('pt-BR')}</p><p class="profile-bio" id="profileHeroBio">${esc(student.bio||'Personalize seu espaço e acompanhe cada conquista.')}</p><div class="profile-pills"><span>Foco: ${esc(student.focus)}</span><span>Meta: ${student.goal} dias por semana</span></div></div></div>
      <div class="learn-stats profile-stats"><span><b>${labelHours()}</b> estudadas neste aparelho</span><span><b>${s.lessons.toLocaleString('pt-BR')}</b> práticas das trilhas</span><span><b>${solvedCount().toLocaleString('pt-BR')}</b> códigos executáveis</span><span><b>${s.missions}</b> etapas de projetos</span><span><b>${s.streak}</b> dias de sequência</span><span><b>${tracks.length}</b> trilhas completas</span></div>
      <div class="profile-dashboard"><section class="profile-panel"><span class="eyebrow">PRÓXIMO MARCO</span><h2>Nível ${level+1}</h2><strong>Faltam ${nextLevel} XP</strong><div class="profile-meter" role="progressbar" aria-label="Progresso para o próximo nível" aria-valuenow="${progress.xp%250}" aria-valuemin="0" aria-valuemax="250"><i style="width:${progress.xp%250/250*100}%"></i></div><p>Cada prática ajuda você a avançar. Seu progresso continua salvo neste aparelho.</p><div class="profile-panel-actions"><button type="button" data-hub-open="practice">Praticar código</button><button type="button" data-hub-open="review">Revisar erros</button></div></section>
      <section class="profile-panel"><span class="eyebrow">SUA PRÓXIMA TRILHA</span><h2>${esc(nearest.title)}</h2><strong>${trackDone}/100 práticas</strong><div class="profile-meter" role="progressbar" aria-label="Progresso na trilha ${esc(nearest.title)}" aria-valuenow="${trackDone}" aria-valuemin="0" aria-valuemax="100"><i style="width:${trackDone}%"></i></div><p>Sua meta pessoal é estudar ${student.goal} dias por semana. Sequência atual: ${s.streak} ${s.streak===1?'dia':'dias'}.</p><div class="profile-panel-actions"><button type="button" data-hub-open="home">Explorar trilhas</button><button type="button" data-hub-open="missions">Missão do Dia</button></div></section></div>
      <section class="profile-edit"><span class="eyebrow">DO SEU JEITO</span><h2>Personalize seu perfil</h2><p>Nome, apresentação, foto e capa deixam esta jornada com a sua cara. As mudanças são salvas neste aparelho.</p><div class="learn-controls"><label>Seu nome<input id="profileName" maxlength="80" value="${esc(student.name)}" placeholder="Como você quer ser chamado(a)?" autocomplete="nickname"></label><label>Foco no momento<select id="profileFocus">${profileFocus.map(value=>`<option value="${esc(value)}" ${student.focus===value?'selected':''}>${esc(value)}</option>`).join('')}</select></label><label>Meta pessoal<select id="profileGoal">${[2,3,5,7].map(days=>`<option value="${days}" ${student.goal===days?'selected':''}>${days} dias por semana</option>`).join('')}</select></label><label class="profile-wide">Sua apresentação<textarea id="profileBio" maxlength="180" placeholder="Ex.: Estou aprendendo Java para criar meus próprios projetos.">${esc(student.bio)}</textarea><small>Até 180 caracteres. Aparece apenas neste aparelho.</small></label><label class="photo-field">Sua foto<input id="profilePhoto" type="file" accept="image/png,image/jpeg,image/webp"></label></div>
      <div class="profile-save-row"><button class="button button-primary" data-save-profile>Salvar perfil</button>${student.photo?'<button class="button button-secondary" data-remove-photo>Remover foto</button>':''}<span class="profile-save-status" id="profileSaveStatus" role="status">Salvo neste aparelho</span></div>
      <div class="profile-colors"><div class="profile-colors-heading"><div><strong>Cor da capa</strong><p>Escolha uma combinação pronta ou crie a sua.</p></div><span id="profileColorName" class="profile-color-name" aria-live="polite">${student.cover==='custom'?'Sua cor · '+student.customColor.toUpperCase():profileColors[student.cover][0]}</span></div><div class="profile-color-list" role="group" aria-label="Cores prontas para a capa">${Object.entries(profileColors).map(([key,[label,shade]])=>`<button type="button" data-profile-cover="${key}" style="--swatch:${shade}" aria-label="Capa ${esc(label)}" aria-pressed="${student.cover===key}" title="${esc(label)}">${student.cover===key?icon('check'):''}</button>`).join('')}</div><div class="profile-custom-choice"><label for="profileCustomColor"><span class="profile-custom-icon" aria-hidden="true">✦</span><span><strong>Crie sua cor</strong><small>Toque para abrir a paleta</small></span><input id="profileCustomColor" type="color" value="${student.customColor}" aria-label="Escolher uma cor personalizada"></label><button type="button" data-profile-custom aria-pressed="${student.cover==='custom'}">Usar minha cor <span id="profileCustomHex">${student.customColor.toUpperCase()}</span></button></div></div><p class="learn-note">Foto, nome, preferências, tempo e progresso ficam guardados apenas neste navegador; sem conta ou sincronização entre aparelhos.</p></section>
      <section class="profile-panel profile-shortcuts"><span class="eyebrow">CONTINUE SUA JORNADA</span><h2>Escolha o próximo passo</h2><div class="profile-quick"><button type="button" data-hub-open="home">Explorar trilhas</button><button type="button" data-hub-open="practice">Ateliê de código</button><button type="button" data-hub-open="lab">Laboratório Swing</button><button type="button" data-hub-open="review">Revisar erros</button></div></section>
      <section class="profile-awards"><span class="eyebrow">CONQUISTAS DA SUA JORNADA</span><h2>Selos e certificados</h2><p>O certificado de uma trilha aparece após as 100 práticas daquela trilha estarem concluídas. Cada trilha tem sua própria arte com nome, data e identificação.</p>${profileBadges()}</section></div>`;
    updateHeaderProfile();
  }
  function certificate(index){const track=earned()[index];if(!track)return;let name=prompt('Nome para o certificado:',student.name||'');if(name===null)return;name=name.trim().slice(0,80);if(!name){toast('Informe um nome para o certificado.');return}const canvas=document.createElement('canvas');canvas.width=1600;canvas.height=1100;const c=canvas.getContext('2d'),color=/^#[0-9a-f]{6}$/i.test(track.color)?track.color:'#177d71';c.fillStyle='#f4f7f5';c.fillRect(0,0,1600,1100);c.fillStyle='#112f32';c.fillRect(0,0,1600,210);c.fillStyle=color;c.fillRect(0,0,24,1100);c.fillRect(0,1060,1600,40);c.fillStyle='#b6eadb';c.font='bold 27px sans-serif';c.fillText('JAVALINGO  ·  CONQUISTA DE APRENDIZAGEM',100,105);c.fillStyle='#fff';c.font='bold 62px sans-serif';c.fillText('Certificado de Trilha',100,175);c.fillStyle='#21534d';c.font='27px sans-serif';c.fillText('CONCLUÍDA COM 100 DE 100 PRÁTICAS',105,305);c.fillStyle='#163c3b';c.font='bold 60px sans-serif';let short=name.length>34?name.slice(0,34)+'…':name;c.fillText(short,105,410);c.fillStyle=color;c.fillRect(105,448,500,5);c.fillStyle='#45625e';c.font='27px sans-serif';c.fillText('Concluiu a trilha de Java:',105,525);c.fillStyle='#173e3d';c.font='bold 47px sans-serif';let title=track.title.length>45?track.title.slice(0,45)+'…':track.title;c.fillText(title,105,605);c.fillStyle='#45625e';c.font='25px sans-serif';c.fillText('Práticas guiadas, leitura de código e resolução de exercícios.',105,675);let date=new Date().toLocaleDateString('pt-BR'),code=`JL-${track.id.replace(/[^a-z0-9-]/gi,'').slice(0,24)}-${new Date().toISOString().slice(0,10)}`;c.font='bold 24px sans-serif';c.fillText('DATA DE EMISSÃO',105,825);c.fillText('IDENTIFICAÇÃO',770,825);c.font='27px sans-serif';c.fillText(date,105,873);c.fillText(code,770,873);c.font='22px sans-serif';c.fillText('Conquista registrada neste aparelho pelo JavaLingo.',105,990);c.fillText('Registro pessoal de aprendizagem; não equivale a certificação oficial.',105,1020);canvas.toBlob(blob=>{if(!blob)return;let u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`JavaLingo-${track.id}-certificado.png`;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)},'image/png')}
  app.addEventListener('input',e=>{if(e.target.id==='profileCustomColor'){if(validProfileColor(e.target.value)){clearTimeout(profileSaveTimer);saveProfileFields();student.customColor=e.target.value;setProfileCover('custom')}return}if(['profileName','profileBio'].includes(e.target.id)){clearTimeout(profileSaveTimer);profileSaveTimer=setTimeout(saveProfileFields,400);return}if(e.target.id!=='javaDictQuery')return;let pos=e.target.selectionStart;dictionaryQuery=e.target.value;dictionaryPage=0;drawDictionaryResults();let target=app.querySelector('#javaDictQuery');target.focus();target.setSelectionRange(pos,pos)});
  app.addEventListener('change',e=>{if(e.target.id==='profileCustomColor'){if(validProfileColor(e.target.value)){student.customColor=e.target.value;setProfileCover('custom')}return}if(['profileName','profileBio'].includes(e.target.id)){clearTimeout(profileSaveTimer);saveProfileFields();return}if(e.target.id==='javaDictKind'){dictionaryKind=e.target.value;dictionaryPage=0;drawDictionaryResults()}if(['profileFocus','profileGoal'].includes(e.target.id)){clearTimeout(profileSaveTimer);saveProfileFields();renderProfile();return}if(e.target.id==='profilePhoto'){clearTimeout(profileSaveTimer);saveProfileFields();let file=e.target.files?.[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024){toast('Escolha uma imagem PNG, JPG ou WebP de até 5 MB.');return}let img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{let canvas=document.createElement('canvas');canvas.width=canvas.height=240;let c=canvas.getContext('2d'),m=Math.min(img.width,img.height);c.drawImage(img,(img.width-m)/2,(img.height-m)/2,m,m,0,0,240,240);student.photo=canvas.toDataURL('image/jpeg',.78);saveStudent();URL.revokeObjectURL(url);renderProfile()};img.onerror=()=>{URL.revokeObjectURL(url);toast('Não foi possível abrir a imagem.')};img.src=url}});
  app.addEventListener('click',e=>{let b=e.target.closest('[data-hub-open],[data-dict-page],[data-practice-go],[data-practice-check],[data-practice-next],[data-practice-random],[data-practice-manual],[data-save-profile],[data-remove-photo],[data-profile-cover],[data-profile-custom],[data-cert]');if(!b)return;if(b.dataset.hubOpen){navigate(b.dataset.hubOpen);return}if(b.dataset.dictPage){dictionaryPage+=b.dataset.dictPage==='next'?1:-1;drawDictionaryResults();return}if(b.hasAttribute('data-practice-go')){let i=Number(app.querySelector('#javaPracticeFamily')?.value),n=Number(app.querySelector('#javaPracticeNumber')?.value);if(!Number.isInteger(i)||i<0||i>=JAVA_PRACTICE_FAMILIES.length||!Number.isInteger(n)||n<1||n>JAVA_PRACTICE_VARIANTS){toast('Escolha um assunto e um número válido.');return}family=i;variant=n;practiceFeedback='';renderPractice();return}if(b.hasAttribute('data-practice-next')){variant=variant%JAVA_PRACTICE_VARIANTS+1;practiceFeedback='';renderPractice();return}if(b.hasAttribute('data-practice-random')){family=Math.floor(Math.random()*JAVA_PRACTICE_FAMILIES.length);variant=1+Math.floor(Math.random()*JAVA_PRACTICE_VARIANTS);practiceFeedback='';renderPractice();return}if(b.hasAttribute('data-practice-check')){checkPractice(editorCode,editorOutput,false);return}if(b.hasAttribute('data-practice-manual')){checkPractice(app.querySelector('#practiceManualCode')?.value||'',app.querySelector('#practiceManualOutput')?.value??null,true);return}if(b.hasAttribute('data-profile-cover')||b.hasAttribute('data-profile-custom')){clearTimeout(profileSaveTimer);saveProfileFields();setProfileCover(b.hasAttribute('data-profile-custom')?'custom':b.dataset.profileCover);return}if(b.hasAttribute('data-save-profile')){clearTimeout(profileSaveTimer);saveProfileFields();renderProfile();toast('Perfil salvo neste aparelho.');return}if(b.hasAttribute('data-remove-photo')){clearTimeout(profileSaveTimer);saveProfileFields();student.photo='';saveStudent();renderProfile();return}if(b.dataset.cert!==undefined)certificate(Number(b.dataset.cert))});
  const previousDone=onPracticeDone;
  onPracticeDone=function(id){previousDone(id);let {trackId}=parseJavaPracticeId(id),t=findJavaTrack(trackId);if(t&&completed(t)===100&&!(student.awarded||{})[trackId]){student.awarded={...(student.awarded||{}),[trackId]:new Date().toISOString()};saveStudent();toast(`Trilha ${t.title} completa! Seu certificado está no perfil.`)}};
  updateHeaderProfile();
  if(screen==='home')app.querySelector('.home-hero')?.insertAdjacentHTML('afterend',invite());
})();
